import{Z as e,e as i,f as o,a0 as n}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Twilio","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/messaging/twilio.md","filePath":"integrations/messaging/twilio.md","lastUpdated":1780377007000}'),a={name:"integrations/messaging/twilio.md"};function s(r,t,l,h,c,g){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="twilio" tabindex="-1">Twilio <a class="header-anchor" href="#twilio" aria-label="Permalink to &quot;Twilio&quot;">​</a></h1><p>Connect Twilio to send a message when a visitor completes your form. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Messaging</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Twilio</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-twilio-api" tabindex="-1">Step 2. Connect to the Twilio API <a class="header-anchor" href="#step-2-connect-to-the-twilio-api" aria-label="Permalink to &quot;Step 2. Connect to the Twilio API&quot;">​</a></h3><ol><li>Go to the <a href="https://www.twilio.com/console" target="_blank">Twilio Console</a> and log in.</li><li>Copy the <strong>Account SID</strong> from Twilio and paste in the <strong>Account SID</strong> field in Formie.</li><li>Copy the <strong>Auth Token</strong> from Twilio and paste in the <strong>Auth Token</strong> field in Formie.</li><li>Navigate to <strong>Phone Numbers</strong> → <strong>Manage</strong> → <strong>Active Numbers</strong>.</li><li>Select a Twilio phone number you own.</li><li>Paste this into the <strong>From Number</strong> field in Formie.</li></ol><h3 id="step-3-test-the-connection" tabindex="-1">Step 3. Test the Connection <a class="header-anchor" href="#step-3-test-the-connection" aria-label="Permalink to &quot;Step 3. Test the Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar to verify the connection.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Set the recipient or channel supported by the integration. Use the variable picker to include the submitted values your team needs in the message.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Check the intended recipient or channel for the test message and verify that its values match the submission.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const p=e(a,[["render",s]]);export{m as __pageData,p as default};
